import tempfile
import torch
import torch.nn as nn
from topologies import Trainer, build, synth
root = tempfile.mkdtemp()
@synth.generator
def samples(ctx):
    x = torch.randn(4, generator=ctx.rng.torch)
    return {'inputs': x, 'target': x[:2]}
class GaussianPredictor(nn.Module):
    def __init__(self):
        super().__init__()
        self.base = build('mlp', 'tiny', in_features=4, out_features=4)
    def forward(self, x):
        raw = self.base(x)
        return {'mean': raw[..., :2], 'variance': torch.nn.functional.softplus(raw[..., 2:]) + 1e-4}
ds = synth.Spec('gaussian-data', generator=samples, size=24, splits={'train': 0.75, 'val': 0.25}, seed=7, root=root, monitor='none').run()
train = ds.for_recipe('structured-objective', split='train')
val = ds.for_recipe('structured-objective', split='val', like=train)
trainer = Trainer(GaussianPredictor(), train, val, recipe='structured-objective', recipe_config={'loss': 'gaussian-nll', 'bindings': {'mean': {'output': 'mean'}, 'targets': {'batch': 'target'}, 'variance': {'output': 'variance'}}}, batch_size=8, max_epochs=1, device='cpu')
trainer.fit()
assert all(torch.isfinite(torch.tensor(v)) for v in trainer.evaluate(val).values())
